//Opens all programs under a chosen domain folder, grabs their error count,
//then sorts in increasing error order and prints them
//@category FunctionID



using generic.stl;
using ghidra.app.script;
using ghidra.framework.model;
using ghidra.framework.model;
using ghidra.program.database;
using ghidra.program.model.listing;
using ghidra.util;
using ghidra.util.exception;
using ghidra.util.exception;

public class FindErrors : GhidraScript {

	/* @Override */
	protected void run()
    {
		DomainFolder folder =
			askProjectFolder("Please select a project folder to RECURSIVELY look for full hash:");

		List<DomainFile> programs = new List<DomainFile>();
		findPrograms(programs, folder);
		List<Pair<DomainFile, Integer>> results = new List<Pair<DomainFile, Integer>>();
		monitor.initialize(programs.size());
		foreach (DomainFile domainFile in programs) {
			if (monitor.isCancelled()) {
				return;
			}
			monitor.incrementProgress(1);
			Program program = null;
			try {
				program = (Program) domainFile.getDomainObject(this, false, false, monitor);
				BookmarkManager bookmarkManager = program.getBookmarkManager();
				int errors = bookmarkManager.getBookmarkCount(BookmarkType.ERROR);
				results.add(new Pair<DomainFile, Integer>(domainFile, errors));
			}
			catch (Exception e) {
				Msg.warn(this, "problem looking at " + domainFile.getName(), e);
			}
			finally {
				if (program != null) {
					program.release(this);
				}
			}
		}

		Collections.sort(results, new Comparator<Pair<DomainFile, Integer>>() {
			/* @Override */
			public int compare(Pair<DomainFile, Integer> o1, Pair<DomainFile, Integer> o2) {
				return o1.second - o2.second;
			}
		});

		foreach (Pair<DomainFile, Integer> pair in results) {
			println(pair.first.toString() + ": " + pair.second);
		}
	}

	private void findPrograms(List<DomainFile> programs, DomainFolder folder)
    {
		DomainFile[] files = folder.getFiles();
		foreach (DomainFile domainFile in files) {
			if (monitor.isCancelled()) {
				return;
			}
			// Do not follow folder-links or consider program links.  Using content type
			// to filter is best way to control this.  If program links should be considered
			// "Program.class.isAssignableFrom(domainFile.getDomainObjectClass())"
			// should be used.
			if (domainFile.getContentType().equals(ProgramContentHandler.PROGRAM_CONTENT_TYPE)) {
				programs.add(domainFile);
			}
		}
		DomainFolder[] folders = folder.getFolders();
		foreach (DomainFolder domainFolder in folders) {
			if (monitor.isCancelled()) {
				return;
			}
			findPrograms(programs, domainFolder);
		}
	}
}
